import { z } from "zod";

export const RETAILERS = ["amazon", "walmart", "target"] as const;
export type RetailerId = (typeof RETAILERS)[number];

export const RETAILER_LABELS: Record<RetailerId, string> = {
  amazon: "Amazon",
  walmart: "Walmart",
  target: "Target",
};

export const CATEGORIES = [
  "Sleep",
  "Feeding",
  "Diapering",
  "Bath",
  "On-the-go",
  "Clothing",
  "Health",
  "Play",
] as const;
export type Category = (typeof CATEGORIES)[number];

export const PRIORITIES = ["must-have", "nice-to-have", "later"] as const;
export type Priority = (typeof PRIORITIES)[number];

export type ItemStatus = "pending" | "keep" | "skip";

export const ParentProfileSchema = z.object({
  dueDate: z.string().nullable(),
  home: z.enum(["apartment", "house", "unknown"]),
  hasCar: z.boolean().nullable(),
  feeding: z.enum(["breast", "formula", "both", "unsure"]),
  budget: z.enum(["lean", "moderate", "generous"]),
  values: z.array(z.string()),
  alreadyHave: z.array(z.string()),
  preferredRetailers: z.array(z.enum(RETAILERS)),
  notes: z.string(),
});
export type ParentProfile = z.infer<typeof ParentProfileSchema>;

export const GeneratedItemSchema = z.object({
  name: z.string(),
  category: z.enum(CATEGORIES),
  priority: z.enum(PRIORITIES),
  reason: z.string(),
  qty: z.number().int().min(1).max(20),
  searchQuery: z.string(),
});
export type GeneratedItem = z.infer<typeof GeneratedItemSchema>;

export type Offer = {
  retailer: RetailerId;
  externalId: string;
  title: string;
  price: number | null;
  imageUrl: string | null;
  url: string;
  rating: number | null;
  inStock: boolean;
};

export type RegistryItem = {
  id: string;
  name: string;
  category: Category;
  priority: Priority;
  reason: string;
  qty: number;
  status: ItemStatus;
  position: number;
  searchQuery: string;
  offers: Array<Offer & { id: string; isPrimary: boolean }>;
  purchased: { buyerName: string | null; retailer: RetailerId | null } | null;
};

export type Registry = {
  id: string;
  slug: string;
  ownerId: string;
  title: string;
  profile: ParentProfile;
  preferredRetailers: RetailerId[];
  dueDate: string | null;
  revision: number;
  items: RegistryItem[];
};

export type ChatMessage = { role: "assistant" | "user"; content: string };

export const EditDiffSchema = z.object({
  summary: z.string(),
  remove: z.array(z.string()).describe("ids of items to remove"),
  add: z.array(GeneratedItemSchema),
  swap: z
    .array(z.object({ id: z.string(), searchQuery: z.string(), reason: z.string() }))
    .describe("items to re-search with a new query"),
});
export type EditDiff = z.infer<typeof EditDiffSchema>;

create extension if not exists pgcrypto;

create table public.registries (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  slug text not null unique check (slug ~ '^[a-z0-9-]{4,64}$'),
  title text not null,
  profile jsonb not null check (jsonb_typeof(profile) = 'object'),
  preferred_retailers text[] not null default '{}',
  due_date date,
  revision bigint not null default 0,
  created_at timestamptz not null default now()
);

create index registries_owner_idx on public.registries (owner_id);

create table public.registry_items (
  id uuid primary key default gen_random_uuid(),
  registry_id uuid not null references public.registries (id) on delete cascade,
  name text not null,
  category text not null,
  priority text not null check (priority in ('must-have', 'nice-to-have', 'later')),
  reason text not null default '',
  qty integer not null default 1 check (qty between 1 and 20),
  status text not null default 'pending' check (status in ('pending', 'keep', 'skip')),
  search_query text not null default '',
  position integer not null default 0
);

create index registry_items_registry_idx on public.registry_items (registry_id, position);

create table public.item_offers (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null references public.registry_items (id) on delete cascade,
  retailer text not null check (retailer in ('amazon', 'walmart', 'target')),
  external_id text not null,
  title text not null,
  price numeric(10, 2),
  image_url text,
  url text not null,
  rating numeric(3, 2),
  in_stock boolean not null default true,
  is_primary boolean not null default false
);

create index item_offers_item_idx on public.item_offers (item_id);

create table public.purchases (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null unique references public.registry_items (id) on delete cascade,
  buyer_name text,
  retailer text check (retailer in ('amazon', 'walmart', 'target')),
  created_at timestamptz not null default now()
);

alter table public.registries enable row level security;
