-- Internal helpers -----------------------------------------------------------

create schema if not exists private;

create or replace function private.insert_offers(p_item_id uuid, p_offers jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.item_offers (item_id, retailer, external_id, title, price, image_url, url, rating, in_stock, is_primary)
  select
    p_item_id,
    o.value ->> 'retailer',
    o.value ->> 'externalId',
    o.value ->> 'title',
    nullif(o.value ->> 'price', '')::numeric,
    o.value ->> 'imageUrl',
    o.value ->> 'url',
    nullif(o.value ->> 'rating', '')::numeric,
    coalesce((o.value ->> 'inStock')::boolean, true),
    o.ordinality = 1
  from jsonb_array_elements(coalesce(p_offers, '[]'::jsonb)) with ordinality as o(value, ordinality);
end;
$$;

create or replace function private.insert_items(p_registry_id uuid, p_items jsonb, p_start integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item jsonb;
  v_index integer := 0;
  v_item_id uuid;
begin
  for v_item in select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    insert into public.registry_items (registry_id, name, category, priority, reason, qty, search_query, position)
    values (
      p_registry_id,
      v_item ->> 'name',
      v_item ->> 'category',
      v_item ->> 'priority',
      coalesce(v_item ->> 'reason', ''),
      coalesce((v_item ->> 'qty')::integer, 1),
      coalesce(v_item ->> 'searchQuery', ''),
      p_start + v_index
    )
    returning id into v_item_id;
    perform private.insert_offers(v_item_id, v_item -> 'offers');
    v_index := v_index + 1;
  end loop;
end;
$$;

create or replace function private.lock_owned_registry(p_registry_id uuid, p_owner_id uuid)
returns public.registries
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_registry public.registries;
begin
  select * into v_registry from public.registries
  where id = p_registry_id and owner_id = p_owner_id
  for update;
  if not found then
    raise exception 'REGISTRY_NOT_FOUND' using errcode = 'P0002';
  end if;
  return v_registry;
end;
$$;

create or replace function private.bump_revision(p_registry_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.registries set revision = revision + 1 where id = p_registry_id;
$$;

-- Public RPCs (service role only) -------------------------------------------

create or replace function public.registry_create(
  p_owner_id uuid,
  p_slug text,
  p_title text,
  p_profile jsonb,
  p_preferred_retailers text[],
  p_due_date date,
  p_items jsonb
)
returns public.registries
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_registry public.registries;
begin
  insert into public.registries (owner_id, slug, title, profile, preferred_retailers, due_date)
  values (p_owner_id, p_slug, p_title, p_profile, coalesce(p_preferred_retailers, '{}'), p_due_date)
  returning * into v_registry;
  perform private.insert_items(v_registry.id, p_items, 0);
  return v_registry;
end;
$$;

create or replace function public.registry_set_item_status(
  p_registry_id uuid,
  p_owner_id uuid,
  p_item_id uuid,
  p_status text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.lock_owned_registry(p_registry_id, p_owner_id);
  update public.registry_items set status = p_status
  where id = p_item_id and registry_id = p_registry_id;
  if not found then
    raise exception 'ITEM_NOT_FOUND' using errcode = 'P0002';
  end if;
  perform private.bump_revision(p_registry_id);
end;
$$;

create or replace function public.registry_set_primary_offer(
  p_registry_id uuid,
  p_owner_id uuid,
  p_item_id uuid,
  p_offer_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.lock_owned_registry(p_registry_id, p_owner_id);
  if not exists (
    select 1 from public.item_offers o
    join public.registry_items i on i.id = o.item_id
    where o.id = p_offer_id and i.id = p_item_id and i.registry_id = p_registry_id
  ) then
    raise exception 'ITEM_NOT_FOUND' using errcode = 'P0002';
  end if;
  update public.item_offers set is_primary = (id = p_offer_id) where item_id = p_item_id;
  perform private.bump_revision(p_registry_id);
end;
$$;

-- p_replace_offers: [{ "itemId": uuid, "searchQuery": text, "reason": text, "offers": [...] }]
create or replace function public.registry_apply_edits(
  p_registry_id uuid,
  p_owner_id uuid,
  p_remove uuid[],
  p_add jsonb,
  p_replace_offers jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_next integer;
  v_swap jsonb;
  v_item_id uuid;
begin
  perform private.lock_owned_registry(p_registry_id, p_owner_id);

  delete from public.registry_items
  where registry_id = p_registry_id and id = any(coalesce(p_remove, '{}'))
    and not exists (select 1 from public.purchases p where p.item_id = registry_items.id);

  for v_swap in select value from jsonb_array_elements(coalesce(p_replace_offers, '[]'::jsonb)) loop
    v_item_id := (v_swap ->> 'itemId')::uuid;
    update public.registry_items
    set search_query = coalesce(v_swap ->> 'searchQuery', search_query),
        reason = coalesce(v_swap ->> 'reason', reason),
        status = 'pending'
    where id = v_item_id and registry_id = p_registry_id;
    if found then
      delete from public.item_offers where item_id = v_item_id;
      perform private.insert_offers(v_item_id, v_swap -> 'offers');
    end if;
  end loop;

  select coalesce(max(position), -1) + 1 into v_next
  from public.registry_items where registry_id = p_registry_id;
  perform private.insert_items(p_registry_id, p_add, v_next);

  perform private.bump_revision(p_registry_id);
end;
$$;

create or replace function public.registry_mark_purchased(
  p_slug text,
  p_item_id uuid,
  p_buyer_name text,
  p_retailer text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_registry_id uuid;
begin
  select r.id into v_registry_id
  from public.registries r
  join public.registry_items i on i.registry_id = r.id
  where r.slug = p_slug and i.id = p_item_id and i.status <> 'skip'
  for update of r;
  if not found then
    raise exception 'ITEM_NOT_FOUND' using errcode = 'P0002';
  end if;

  begin
    insert into public.purchases (item_id, buyer_name, retailer)
    values (p_item_id, nullif(trim(p_buyer_name), ''), p_retailer);
  exception when unique_violation then
    raise exception 'ALREADY_PURCHASED' using errcode = 'P0001';
  end;

  perform private.bump_revision(v_registry_id);
end;
$$;

revoke all on function
  private.insert_offers(uuid, jsonb),
  private.insert_items(uuid, jsonb, integer),
  private.lock_owned_registry(uuid, uuid),
  private.bump_revision(uuid),
  public.registry_create(uuid, text, text, jsonb, text[], date, jsonb),
  public.registry_set_item_status(uuid, uuid, uuid, text),
  public.registry_set_primary_offer(uuid, uuid, uuid, uuid),
  public.registry_apply_edits(uuid, uuid, uuid[], jsonb, jsonb),
  public.registry_mark_purchased(text, uuid, text, text)
from public, anon, authenticated;

grant execute on function
  public.registry_create(uuid, text, text, jsonb, text[], date, jsonb),
  public.registry_set_item_status(uuid, uuid, uuid, text),
  public.registry_set_primary_offer(uuid, uuid, uuid, uuid),
  public.registry_apply_edits(uuid, uuid, uuid[], jsonb, jsonb),
  public.registry_mark_purchased(text, uuid, text, text)
to service_role;

-- Live updates for the share page -------------------------------------------

create or replace function private.broadcast_registry_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  perform realtime.send(
    jsonb_build_object('revision', new.revision),
    'registry_changed',
    'registry:' || new.slug,
    false
  );
  return null;
end;
$$;

revoke all on function private.broadcast_registry_update() from public, anon, authenticated;
grant execute on function private.broadcast_registry_update() to service_role;

create trigger registries_broadcast_update
after update of revision on public.registries
for each row execute function private.broadcast_registry_update();

import "server-only";
import { promises as fs } from "node:fs";
import path from "node:path";
import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import type {
  GeneratedItem,
  ItemStatus,
  Offer,
  ParentProfile,
  Registry,
  RegistryItem,
  RetailerId,
} from "./types";

export type NewItem = GeneratedItem & { offers: Offer[] };
export type OfferSwap = { itemId: string; searchQuery: string; reason: string; offers: Offer[] };

export type CreateRegistryInput = {
  ownerId: string;
  title: string;
  profile: ParentProfile;
  items: NewItem[];
};

export class RegistryError extends Error {}

function friendlyError(message: string | undefined) {
  if (message?.includes("REGISTRY_NOT_FOUND")) return "Registry not found.";
  if (message?.includes("ITEM_NOT_FOUND")) return "That item is not on this registry.";
  if (message?.includes("ALREADY_PURCHASED")) return "Someone already bought this one.";
  return "The registry could not be updated.";
}

export function isSupabaseConfigured() {
  return Boolean(
    process.env.SUPABASE_URL && (process.env.SUPABASE_SECRET_KEY ?? process.env.SUPABASE_SERVICE_ROLE_KEY),
  );
}

let supabaseAdmin: SupabaseClient | null = null;

export function getSupabaseAdmin() {
  if (supabaseAdmin) return supabaseAdmin;
  const url = process.env.SUPABASE_URL;
  const key = process.env.SUPABASE_SECRET_KEY ?? process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) throw new RegistryError("Supabase storage is not configured.");
  supabaseAdmin = createClient(url, key, { auth: { autoRefreshToken: false, persistSession: false } });
  return supabaseAdmin;
}

function makeSlug(title: string) {
  const base = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40) || "registry";
  const suffix = Array.from(crypto.getRandomValues(new Uint8Array(3)), (b) => b.toString(16).padStart(2, "0")).join("");
  return `${base}-${suffix}`;
}

// ---------------------------------------------------------------------------
// Supabase implementation

type ItemRow = {
  id: string;
  name: string;
  category: RegistryItem["category"];
  priority: RegistryItem["priority"];
  reason: string;
  qty: number;
  status: ItemStatus;
  position: number;
  search_query: string;
  item_offers: Array<{
    id: string;
    retailer: RetailerId;
    external_id: string;
    title: string;
    price: number | string | null;
    image_url: string | null;
    url: string;
    rating: number | string | null;
    in_stock: boolean;
    is_primary: boolean;
  }>;
  purchases: Array<{ buyer_name: string | null; retailer: RetailerId | null }> | { buyer_name: string | null; retailer: RetailerId | null } | null;
};

type RegistryRow = {
  id: string;
  slug: string;
  owner_id: string;
  title: string;
  profile: ParentProfile;
  preferred_retailers: RetailerId[];
  due_date: string | null;
  revision: number | string;
  registry_items: ItemRow[];
};

const REGISTRY_SELECT =
  "id, slug, owner_id, title, profile, preferred_retailers, due_date, revision, registry_items(id, name, category, priority, reason, qty, status, position, search_query, item_offers(*), purchases(buyer_name, retailer))";

function toRegistry(row: RegistryRow): Registry {
  const items = [...row.registry_items]
    .sort((a, b) => a.position - b.position)
    .map((item): RegistryItem => {
      const purchase = Array.isArray(item.purchases) ? item.purchases[0] : item.purchases;
      return {
        id: item.id,
        name: item.name,
        category: item.category,
        priority: item.priority,
        reason: item.reason,
        qty: item.qty,
        status: item.status,
        position: item.position,
        searchQuery: item.search_query,
        offers: [...item.item_offers]
          .sort((a, b) => Number(b.is_primary) - Number(a.is_primary))
          .map((o) => ({
            id: o.id,
            retailer: o.retailer,
            externalId: o.external_id,
            title: o.title,
            price: o.price === null ? null : Number(o.price),
            imageUrl: o.image_url,
            url: o.url,
            rating: o.rating === null ? null : Number(o.rating),
            inStock: o.in_stock,
            isPrimary: o.is_primary,
          })),
        purchased: purchase ? { buyerName: purchase.buyer_name, retailer: purchase.retailer } : null,
      };
    });
  return {
    id: row.id,
    slug: row.slug,
    ownerId: row.owner_id,
    title: row.title,
    profile: row.profile,
    preferredRetailers: row.preferred_retailers,
    dueDate: row.due_date,
    revision: Number(row.revision),
    items,
  };
}

const supabaseStore = {
  async create(input: CreateRegistryInput) {
    for (let attempt = 0; attempt < 5; attempt += 1) {
      const { data, error } = await getSupabaseAdmin()
        .rpc("registry_create", {
          p_owner_id: input.ownerId,
          p_slug: makeSlug(input.title),
          p_title: input.title,
          p_profile: input.profile,
          p_preferred_retailers: input.profile.preferredRetailers,
          p_due_date: input.profile.dueDate,
          p_items: input.items,
        })
        .single();
      if (!error && data) return (data as { id: string }).id;
      if (error?.code !== "23505") throw new RegistryError(friendlyError(error?.message));
    }
    throw new RegistryError("A unique link could not be created. Please try again.");
  },

  async getById(id: string) {
    const { data, error } = await getSupabaseAdmin().from("registries").select(REGISTRY_SELECT).eq("id", id).maybeSingle();
    if (error) throw new RegistryError(friendlyError(error.message));
    return data ? toRegistry(data as unknown as RegistryRow) : null;
  },

  async getBySlug(slug: string) {
    const { data, error } = await getSupabaseAdmin().from("registries").select(REGISTRY_SELECT).eq("slug", slug).maybeSingle();
    if (error) throw new RegistryError(friendlyError(error.message));
    return data ? toRegistry(data as unknown as RegistryRow) : null;
  },

  async listForOwner(ownerId: string) {
    const { data, error } = await getSupabaseAdmin()
      .from("registries")
      .select("id, slug, title, created_at")
      .eq("owner_id", ownerId)
      .order("created_at", { ascending: false });
    if (error) throw new RegistryError(friendlyError(error.message));
    return (data ?? []) as Array<{ id: string; slug: string; title: string }>;
  },

  async rpc(name: string, args: Record<string, unknown>) {
    const { error } = await getSupabaseAdmin().rpc(name, args);
    if (error) throw new RegistryError(friendlyError(error.message));
  },

  async setItemStatus(registryId: string, ownerId: string, itemId: string, status: ItemStatus) {
    await this.rpc("registry_set_item_status", {
      p_registry_id: registryId,
      p_owner_id: ownerId,
      p_item_id: itemId,
      p_status: status,
    });
  },

  async setPrimaryOffer(registryId: string, ownerId: string, itemId: string, offerId: string) {
    await this.rpc("registry_set_primary_offer", {
      p_registry_id: registryId,
      p_owner_id: ownerId,
      p_item_id: itemId,
      p_offer_id: offerId,
    });
  },

  async applyEdits(registryId: string, ownerId: string, remove: string[], add: NewItem[], swaps: OfferSwap[]) {
    await this.rpc("registry_apply_edits", {
      p_registry_id: registryId,
      p_owner_id: ownerId,
      p_remove: remove,
      p_add: add,
      p_replace_offers: swaps,
    });
  },

  async markPurchased(slug: string, itemId: string, buyerName: string | null, retailer: RetailerId | null) {
    await this.rpc("registry_mark_purchased", {
      p_slug: slug,
      p_item_id: itemId,
      p_buyer_name: buyerName,
      p_retailer: retailer,
    });
  },
};

// ---------------------------------------------------------------------------
// Local JSON-file implementation, used only when Supabase is not configured so
// the app can be tried end to end without any accounts.

const LOCAL_FILE = path.join(process.cwd(), ".data", "registries.json");

async function readLocal(): Promise<Registry[]> {
  try {
    return JSON.parse(await fs.readFile(LOCAL_FILE, "utf8")) as Registry[];
  } catch {
    return [];
  }
}

async function writeLocal(registries: Registry[]) {
  await fs.mkdir(path.dirname(LOCAL_FILE), { recursive: true });
  await fs.writeFile(LOCAL_FILE, JSON.stringify(registries, null, 2));
}

function toLocalItem(item: NewItem, position: number): RegistryItem {
  return {
    id: crypto.randomUUID(),
    name: item.name,
    category: item.category,
    priority: item.priority,
    reason: item.reason,
    qty: item.qty,
    status: "pending",
    position,
    searchQuery: item.searchQuery,
    offers: item.offers.map((o, i) => ({ ...o, id: crypto.randomUUID(), isPrimary: i === 0 })),
    purchased: null,
  };
}

async function mutateLocal(registryId: string, ownerId: string, fn: (r: Registry) => void) {
  const all = await readLocal();
  const registry = all.find((r) => r.id === registryId && r.ownerId === ownerId);
  if (!registry) throw new RegistryError("Registry not found.");
  fn(registry);
  registry.revision += 1;
  await writeLocal(all);
}

function findItem(registry: Registry, itemId: string) {
  const item = registry.items.find((i) => i.id === itemId);
  if (!item) throw new RegistryError("That item is not on this registry.");
  return item;
}

const localStore: typeof supabaseStore = {
  async create(input) {
    const all = await readLocal();
    const registry: Registry = {
      id: crypto.randomUUID(),
      slug: makeSlug(input.title),
      ownerId: input.ownerId,
      title: input.title,
      profile: input.profile,
      preferredRetailers: input.profile.preferredRetailers,
      dueDate: input.profile.dueDate,
      revision: 0,
      items: input.items.map(toLocalItem),
    };
    all.push(registry);
    await writeLocal(all);
    return registry.id;
  },
  async getById(id) {
    return (await readLocal()).find((r) => r.id === id) ?? null;
  },
  async getBySlug(slug) {
    return (await readLocal()).find((r) => r.slug === slug) ?? null;
  },
  async listForOwner(ownerId) {
    return (await readLocal())
      .filter((r) => r.ownerId === ownerId)
      .reverse()
      .map(({ id, slug, title }) => ({ id, slug, title }));
  },
  async rpc() {},
  async setItemStatus(registryId, ownerId, itemId, status) {
    await mutateLocal(registryId, ownerId, (r) => {
      findItem(r, itemId).status = status;
    });
  },
  async setPrimaryOffer(registryId, ownerId, itemId, offerId) {
    await mutateLocal(registryId, ownerId, (r) => {
      const item = findItem(r, itemId);
      if (!item.offers.some((o) => o.id === offerId)) throw new RegistryError("That item is not on this registry.");
      item.offers.forEach((o) => (o.isPrimary = o.id === offerId));
      item.offers.sort((a, b) => Number(b.isPrimary) - Number(a.isPrimary));
    });
  },
  async applyEdits(registryId, ownerId, remove, add, swaps) {
    await mutateLocal(registryId, ownerId, (r) => {
      r.items = r.items.filter((i) => !remove.includes(i.id) || i.purchased);
      for (const swap of swaps) {
        const item = r.items.find((i) => i.id === swap.itemId);
        if (!item) continue;
        item.searchQuery = swap.searchQuery;
        item.reason = swap.reason;
        item.status = "pending";
        item.offers = swap.offers.map((o, i) => ({ ...o, id: crypto.randomUUID(), isPrimary: i === 0 }));
      }
      const start = r.items.reduce((max, i) => Math.max(max, i.position), -1) + 1;
      r.items.push(...add.map((item, i) => toLocalItem(item, start + i)));
    });
  },
  async markPurchased(slug, itemId, buyerName, retailer) {
    const all = await readLocal();
    const registry = all.find((r) => r.slug === slug);
    if (!registry) throw new RegistryError("Registry not found.");
    const item = findItem(registry, itemId);
    if (item.status === "skip") throw new RegistryError("That item is not on this registry.");
    if (item.purchased) throw new RegistryError("Someone already bought this one.");
    item.purchased = { buyerName: buyerName?.trim() || null, retailer };
    registry.revision += 1;
    await writeLocal(all);
  },
};

export function registryStore() {
  return isSupabaseConfigured() ? supabaseStore : localStore;
}

import "server-only";
import { getSupabaseAdmin, isSupabaseConfigured } from "./registry-store";

const LOCAL_OWNER_ID = "00000000-0000-0000-0000-000000000001";

export async function getOwnerId(request: Request): Promise<string | null> {
  if (!isSupabaseConfigured()) return LOCAL_OWNER_ID;
  const token = request.headers.get("authorization")?.replace(/^Bearer\s+/i, "");
  if (!token) return null;
  const { data, error } = await getSupabaseAdmin().auth.getUser(token);
  if (error || !data.user) return null;
  return data.user.id;
}

export function unauthorized() {
  return Response.json({ error: "Please sign in to continue." }, { status: 401 });
}

import type { Offer, RetailerId } from "../types";

export type SearchFilters = { maxPrice?: number };

export interface RetailerProvider {
  id: RetailerId;
  /** True when real credentials are present; otherwise the mock is used. */
  isConfigured(): boolean;
  search(query: string, filters: SearchFilters): Promise<Offer[]>;
}

import { createHash, createHmac } from "node:crypto";
import type { Offer } from "../types";
import type { RetailerProvider } from "./provider";

const HOST = "webservices.amazon.com";
const REGION = "us-east-1";
const SERVICE = "ProductAdvertisingAPI";
const PATH = "/paapi5/searchitems";
const TARGET = "com.amazon.paapi5.v1.ProductAdvertisingAPIv1.SearchItems";

function sha256(value: string) {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function hmac(key: Buffer | string, value: string) {
  return createHmac("sha256", key).update(value, "utf8").digest();
}

function signHeaders(body: string, accessKey: string, secretKey: string) {
  const amzDate = new Date().toISOString().replace(/[:-]|\.\d{3}/g, "");
  const dateStamp = amzDate.slice(0, 8);
  const headers: Record<string, string> = {
    "content-encoding": "amz-1.0",
    "content-type": "application/json; charset=utf-8",
    host: HOST,
    "x-amz-date": amzDate,
    "x-amz-target": TARGET,
  };
  const signedHeaders = Object.keys(headers).sort().join(";");
  const canonicalHeaders = Object.keys(headers)
    .sort()
    .map((k) => `${k}:${headers[k]}\n`)
    .join("");
  const canonicalRequest = ["POST", PATH, "", canonicalHeaders, signedHeaders, sha256(body)].join("\n");
  const scope = `${dateStamp}/${REGION}/${SERVICE}/aws4_request`;
  const stringToSign = ["AWS4-HMAC-SHA256", amzDate, scope, sha256(canonicalRequest)].join("\n");
  const signingKey = hmac(hmac(hmac(hmac(`AWS4${secretKey}`, dateStamp), REGION), SERVICE), "aws4_request");
  const signature = createHmac("sha256", signingKey).update(stringToSign, "utf8").digest("hex");
  headers.authorization = `AWS4-HMAC-SHA256 Credential=${accessKey}/${scope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
  return headers;
}

type PaapiItem = {
  ASIN: string;
  DetailPageURL: string;
  ItemInfo?: { Title?: { DisplayValue?: string } };
  Images?: { Primary?: { Medium?: { URL?: string } } };
  Offers?: { Listings?: Array<{ Price?: { Amount?: number }; Availability?: { Type?: string } }> };
  CustomerReviews?: { StarRating?: { Value?: number } };
};

export const amazonProvider: RetailerProvider = {
  id: "amazon",
  isConfigured() {
    return Boolean(
      process.env.AMAZON_PAAPI_ACCESS_KEY && process.env.AMAZON_PAAPI_SECRET && process.env.AMAZON_PARTNER_TAG,
    );
  },
  async search(query, filters) {
    const body = JSON.stringify({
      Keywords: query,
      SearchIndex: "Baby",
      ItemCount: 3,
      PartnerTag: process.env.AMAZON_PARTNER_TAG,
      PartnerType: "Associates",
      Marketplace: "www.amazon.com",
      ...(filters.maxPrice ? { MaxPrice: Math.round(filters.maxPrice * 100) } : {}),
      Resources: [
        "ItemInfo.Title",
        "Images.Primary.Medium",
        "Offers.Listings.Price",
        "Offers.Listings.Availability.Type",
        "CustomerReviews.StarRating",
      ],
    });
    const response = await fetch(`https://${HOST}${PATH}`, {
      method: "POST",
      headers: signHeaders(body, process.env.AMAZON_PAAPI_ACCESS_KEY!, process.env.AMAZON_PAAPI_SECRET!),
      body,
    });
    if (!response.ok) throw new Error(`Amazon search failed (${response.status})`);
    const data = (await response.json()) as { SearchResult?: { Items?: PaapiItem[] } };
    return (data.SearchResult?.Items ?? []).map(
      (item): Offer => ({
        retailer: "amazon",
        externalId: item.ASIN,
        title: item.ItemInfo?.Title?.DisplayValue ?? query,
        price: item.Offers?.Listings?.[0]?.Price?.Amount ?? null,
        imageUrl: item.Images?.Primary?.Medium?.URL ?? null,
        url: item.DetailPageURL,
        rating: item.CustomerReviews?.StarRating?.Value ?? null,
        inStock: item.Offers?.Listings?.[0]?.Availability?.Type !== "OutOfStock",
      }),
    );
  },
};

import { createSign } from "node:crypto";
import type { Offer } from "../types";
import type { RetailerProvider } from "./provider";

type WalmartItem = {
  itemId: number;
  name: string;
  salePrice?: number;
  mediumImage?: string;
  thumbnailImage?: string;
  productTrackingUrl?: string;
  productUrl?: string;
  customerRating?: string;
  stock?: string;
};

function authHeaders() {
  const consumerId = process.env.WALMART_CONSUMER_ID!;
  const keyVersion = process.env.WALMART_KEY_VERSION ?? "1";
  const privateKey = process.env.WALMART_PRIVATE_KEY!.replace(/\\n/g, "\n");
  const timestamp = Date.now().toString();
  const signer = createSign("RSA-SHA256");
  signer.update(`${consumerId}\n${timestamp}\n${keyVersion}\n`);
  return {
    "WM_CONSUMER.ID": consumerId,
    "WM_CONSUMER.INTIMESTAMP": timestamp,
    "WM_SEC.KEY_VERSION": keyVersion,
    "WM_SEC.AUTH_SIGNATURE": signer.sign(privateKey, "base64"),
  };
}

export const walmartProvider: RetailerProvider = {
  id: "walmart",
  isConfigured() {
    return Boolean(
      process.env.WALMART_CONSUMER_ID && process.env.WALMART_PRIVATE_KEY && process.env.WALMART_PUBLISHER_ID,
    );
  },
  async search(query, filters) {
    const params = new URLSearchParams({
      query,
      numItems: "3",
      publisherId: process.env.WALMART_PUBLISHER_ID!,
    });
    const response = await fetch(
      `https://developer.api.walmart.com/api-proxy/service/affil/product/v2/search?${params}`,
      { headers: authHeaders() },
    );
    if (!response.ok) throw new Error(`Walmart search failed (${response.status})`);
    const data = (await response.json()) as { items?: WalmartItem[] };
    return (data.items ?? [])
      .filter((item) => !filters.maxPrice || (item.salePrice ?? 0) <= filters.maxPrice)
      .map(
        (item): Offer => ({
          retailer: "walmart",
          externalId: String(item.itemId),
          title: item.name,
          price: item.salePrice ?? null,
          imageUrl: item.mediumImage ?? item.thumbnailImage ?? null,
          url: item.productTrackingUrl ?? item.productUrl ?? `https://www.walmart.com/ip/${item.itemId}`,
          rating: item.customerRating ? Number(item.customerRating) : null,
          inStock: item.stock !== "Not available",
        }),
      );
  },
};

