import type { Offer, RetailerId } from "../types";

const SEARCH_URLS: Record<RetailerId, (q: string) => string> = {
  amazon: (q) => `https://www.amazon.com/s?k=${encodeURIComponent(q)}`,
  walmart: (q) => `https://www.walmart.com/search?q=${encodeURIComponent(q)}`,
  target: (q) => `https://www.target.com/s?searchTerm=${encodeURIComponent(q)}`,
};

const BRANDS = ["Little Lark", "Cozy Sprout", "Bramble & Bee", "Nestwell", "Puddle Duck"];

const PRICE_HINTS: Array<[RegExp, number]> = [
  [/stroller|car seat|crib|glider|travel system/i, 220],
  [/bassinet|monitor|high chair|pump|carrier|play ?yard/i, 110],
  [/swaddle|sleep sack|bottle|carrier|bath|diaper bag|mattress/i, 35],
  [/diaper|wipe|onesie|bodysuit|sock|burp|bib|pacifier/i, 18],
];

function hash(value: string) {
  let h = 2166136261;
  for (const c of value) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  return Math.abs(h);
}

export function mockSearch(retailer: RetailerId, query: string, maxPrice?: number): Offer[] {
  const base = PRICE_HINTS.find(([pattern]) => pattern.test(query))?.[1] ?? 28;
  return [0, 1].map((variant) => {
    const seed = hash(`${retailer}:${query}:${variant}`);
    const brand = BRANDS[seed % BRANDS.length];
    let price = Math.round(base * (0.7 + (seed % 60) / 100)) - 0.01;
    if (maxPrice && price > maxPrice) price = Math.max(4.99, Math.floor(maxPrice) - 0.01);
    return {
      retailer,
      externalId: `mock-${seed.toString(36)}`,
      title: `${brand} ${query.replace(/\b\w/g, (c) => c.toUpperCase())}`,
      price,
      imageUrl: null,
      url: SEARCH_URLS[retailer](query),
      rating: 4 + (seed % 10) / 10,
      inStock: true,
    };
  });
}

import "server-only";
import type { Offer, RetailerId } from "../types";
import { amazonProvider } from "./amazon";
import { mockSearch } from "./mock";
import type { RetailerProvider, SearchFilters } from "./provider";
import { targetProvider } from "./target";
import { walmartProvider } from "./walmart";

const PROVIDERS: RetailerProvider[] = [amazonProvider, walmartProvider, targetProvider];
const TIMEOUT_MS = 6000;
const MAX_OFFERS = 4;

function withTimeout<T>(promise: Promise<T>, ms: number) {
  return Promise.race([
    promise,
    new Promise<never>((_, reject) => setTimeout(() => reject(new Error("timeout")), ms)),
  ]);
}

function normalize(title: string) {
  return title.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim().split(" ").slice(0, 6).join(" ");
}

async function searchProvider(provider: RetailerProvider, query: string, filters: SearchFilters) {
  if (!provider.isConfigured()) return mockSearch(provider.id, query, filters.maxPrice);
  try {
    return await withTimeout(provider.search(query, filters), TIMEOUT_MS);
  } catch (error) {
    console.warn(`[retail] ${provider.id} search failed for "${query}"`, error);
    return [];
  }
}

function score(offer: Offer, preferred: RetailerId[]) {
  const preference = preferred.includes(offer.retailer) ? 2 : 0;
  const rating = offer.rating ?? 4;
  const stock = offer.inStock ? 0 : -5;
  return preference + rating + stock;
}

/** Search every retailer, then interleave so each store's best match surfaces. */
export async function findOffers(query: string, preferred: RetailerId[], filters: SearchFilters = {}) {
  const results = await Promise.all(PROVIDERS.map((p) => searchProvider(p, query, filters)));
  const seen = new Set<string>();
  const perRetailer = results.map((offers) =>
    offers
      .filter((o) => {
        const key = `${o.retailer}:${normalize(o.title)}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .sort((a, b) => score(b, preferred) - score(a, preferred)),
  );

  const firsts = perRetailer.flatMap((offers) => offers.slice(0, 1));
  const rest = perRetailer.flatMap((offers) => offers.slice(1));
  firsts.sort((a, b) => score(b, preferred) - score(a, preferred));
  rest.sort((a, b) => score(b, preferred) - score(a, preferred));
  return [...firsts, ...rest].slice(0, MAX_OFFERS);
}

export async function mapLimit<T, R>(items: T[], limit: number, fn: (item: T) => Promise<R>) {
  const out: R[] = new Array(items.length);
  let next = 0;
  await Promise.all(
    Array.from({ length: Math.min(limit, items.length) }, async () => {
      while (next < items.length) {
        const index = next++;
        out[index] = await fn(items[index]);
      }
    }),
  );
  return out;
}

export function liveRetailers() {
  return PROVIDERS.filter((p) => p.isConfigured()).map((p) => p.id);
}

import "server-only";
import { z } from "zod";

export function isOpenAIConfigured() {
  return Boolean(process.env.OPENAI_API_KEY);
}

type Message = { role: "system" | "user" | "assistant"; content: string };

export async function callJson<T extends z.ZodType>(name: string, schema: T, messages: Message[]): Promise<z.infer<T>> {
  const response = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
    },
    body: JSON.stringify({
      model: process.env.OPENAI_MODEL ?? "gpt-4o",
      temperature: 0.4,
      messages,
      response_format: {
        type: "json_schema",
        json_schema: { name, schema: z.toJSONSchema(schema), strict: false },
      },
    }),
  });
  if (!response.ok) {
    throw new Error(`OpenAI request failed (${response.status}): ${(await response.text()).slice(0, 300)}`);
  }
  const data = (await response.json()) as { choices: Array<{ message: { content: string } }> };
  return schema.parse(JSON.parse(data.choices[0].message.content));
}

import "server-only";
import { z } from "zod";
import { ParentProfileSchema, type ChatMessage, type ParentProfile, type RetailerId } from "../types";
import { callJson, isOpenAIConfigured } from "./openai";

export const IntakeTurnSchema = z.object({
  reply: z.string().describe("Your next short, warm message. One question at a time."),
  chips: z.array(z.string()).describe("2-5 short tap-to-answer options for the question you asked"),
  done: z.boolean().describe("True once you know enough to build the registry"),
  profile: ParentProfileSchema.nullable().describe("Filled in only when done is true"),
});
export type IntakeTurn = z.infer<typeof IntakeTurnSchema>;

const SYSTEM_PROMPT = `You are a calm, kind registry helper for an expecting parent who is likely tired and overwhelmed.
Your job: learn just enough to build a great baby registry, in as few questions as possible (6-9 total).
Rules:
- Ask ONE short question per message. Never lecture. Never list more than one question.
- Briefly acknowledge their answer (a few words) before the next question.
- Always offer 2-5 tap-to-answer chips matching your question.
- Cover, in roughly this order, skipping anything they've already told you:
  due date; home (apartment/house); whether they drive; feeding plans; budget (lean/moderate/generous);
  things they already have or are getting handed down; values (eco-friendly, minimal, gender-neutral, etc.);
  favorite stores (Amazon, Walmart, Target).
- If they say "I don't know" or "skip", pick a sensible default and move on. Reassure them that's fine.
- When you have enough, set done=true, fill in profile, and reply with one encouraging sentence
  saying you're building their registry now.
- preferredRetailers may only contain "amazon", "walmart", "target".
- dueDate is ISO yyyy-mm-dd or null. Today is ${new Date().toISOString().slice(0, 10)}.`;

export const OPENING: IntakeTurn = {
  reply:
    "Hi! I'll put together a registry for you, so you don't have to start from a blank page. Just a few quick questions, and you can tap an answer or type anything. First, when is your little one due?",
  chips: ["In 1-2 months", "In 3-5 months", "6+ months away", "Not sure yet"],
  done: false,
  profile: null,
};

export async function nextIntakeTurn(messages: ChatMessage[]): Promise<IntakeTurn> {
  if (!isOpenAIConfigured()) return mockIntakeTurn(messages);
  return callJson("intake_turn", IntakeTurnSchema, [{ role: "system", content: SYSTEM_PROMPT }, ...messages]);
}

// ---------------------------------------------------------------------------
// Scripted fallback so the flow works without an OpenAI key.

const SCRIPT: Array<Omit<IntakeTurn, "done" | "profile">> = [
  OPENING,
  { reply: "Lovely. Do you live in an apartment or a house?", chips: ["Apartment", "House", "Something else"] },
  { reply: "Got it. Will you be driving with baby much?", chips: ["Yes, we drive", "Mostly walk / transit", "A bit of both"] },
  { reply: "How are you thinking about feeding? Totally fine to not know yet.", chips: ["Breastfeeding", "Formula", "A mix", "Not sure"] },
  { reply: "What budget feels comfortable for the registry overall?", chips: ["Keep it lean", "Moderate", "Generous"] },
  { reply: "Anything you already have or are getting handed down?", chips: ["Crib", "Stroller", "Car seat", "Nothing yet"] },
  { reply: "Any values that matter to you?", chips: ["Eco-friendly", "Minimal", "Gender-neutral", "No preference"] },
  { reply: "Last one! Where do your friends and family like to shop?", chips: ["Amazon", "Target", "Walmart", "Any of them"] },
];

function answers(messages: ChatMessage[]) {
  return messages.filter((m) => m.role === "user").map((m) => m.content.toLowerCase());
}

function dueDateFrom(answer: string) {
  const months = /1-2/.test(answer) ? 1.5 : /3-5/.test(answer) ? 4 : /6\+/.test(answer) ? 6.5 : null;
  const explicit = answer.match(/\d{4}-\d{2}-\d{2}/)?.[0];
  if (explicit) return explicit;
  if (months === null) return null;
  const date = new Date(Date.now() + months * 30 * 24 * 3600 * 1000);
  return date.toISOString().slice(0, 10);
}

export function mockProfile(messages: ChatMessage[]): ParentProfile {
  const a = answers(messages);
  const at = (i: number) => a[i] ?? "";
  const stores: RetailerId[] = (["amazon", "walmart", "target"] as const).filter((s) => at(7).includes(s));
  const haves = ["crib", "stroller", "car seat", "bassinet", "high chair", "bouncer"].filter((h) => at(5).includes(h));
  const values = ["eco", "minimal", "gender-neutral"].filter((v) => at(6).includes(v));
  return {
    dueDate: dueDateFrom(at(0)),
    home: at(1).includes("apartment") ? "apartment" : at(1).includes("house") ? "house" : "unknown",
    hasCar: at(2).includes("walk") || at(2).includes("transit") ? false : at(2) ? true : null,
    feeding: at(3).includes("mix") || at(3).includes("both")
      ? "both"
      : at(3).includes("breast")
        ? "breast"
        : at(3).includes("formula")
          ? "formula"
          : "unsure",
    budget: at(4).includes("lean") ? "lean" : at(4).includes("generous") ? "generous" : "moderate",
    values,
    alreadyHave: haves,
    preferredRetailers: stores,
    notes: "",
  };
}

function mockIntakeTurn(messages: ChatMessage[]): IntakeTurn {
  const answered = answers(messages).length;
  if (answered >= SCRIPT.length) {
    return {
      reply: "Thank you, that's everything I need. Building your registry now. Take a breath, I've got this part.",
      chips: [],
      done: true,
      profile: mockProfile(messages),
    };
  }
  return { ...SCRIPT[answered], done: false, profile: null };
}

