import { getOwnerId, unauthorized } from "@/lib/auth";
import { registryStore, RegistryError } from "@/lib/registry-store";
import type { ItemStatus } from "@/lib/types";

export const runtime = "nodejs";

type RouteContext = { params: Promise<{ id: string }> };
type Action =
  | { action: "status"; itemId: string; status: ItemStatus }
  | { action: "primary"; itemId: string; offerId: string };

const STATUSES: ItemStatus[] = ["pending", "keep", "skip"];

export async function GET(request: Request, context: RouteContext) {
  const { id } = await context.params;
  const ownerId = await getOwnerId(request);
  if (!ownerId) return unauthorized();
  try {
    const registry = await registryStore().getById(id);
    if (!registry || registry.ownerId !== ownerId) return Response.json({ error: "Registry not found." }, { status: 404 });
    return Response.json({ registry }, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return Response.json({ error: error instanceof RegistryError ? error.message : "Could not load registry." }, { status: 503 });
  }
}

export async function PATCH(request: Request, context: RouteContext) {
  const { id } = await context.params;
  const ownerId = await getOwnerId(request);
  if (!ownerId) return unauthorized();

  const input = (await request.json().catch(() => null)) as Action | null;
  try {
    const store = registryStore();
    if (input?.action === "status" && STATUSES.includes(input.status)) {
      await store.setItemStatus(id, ownerId, input.itemId, input.status);
    } else if (input?.action === "primary" && input.offerId) {
      await store.setPrimaryOffer(id, ownerId, input.itemId, input.offerId);
    } else {
      return Response.json({ error: "Unknown action." }, { status: 400 });
    }
    return Response.json({ ok: true });
  } catch (error) {
    return Response.json({ error: error instanceof RegistryError ? error.message : "Could not update." }, { status: 409 });
  }
}

import { proposeEdit } from "@/lib/ai/edit";
import { getOwnerId, unauthorized } from "@/lib/auth";
import { withOffers } from "@/lib/offers";
import { findOffers, mapLimit } from "@/lib/retail/aggregator";
import { registryStore, RegistryError } from "@/lib/registry-store";
import { EditDiffSchema } from "@/lib/types";

export const runtime = "nodejs";
export const maxDuration = 120;

type RouteContext = { params: Promise<{ id: string }> };

/** { request } -> preview diff.  { diff } -> apply a previously previewed diff. */
export async function POST(request: Request, context: RouteContext) {
  const { id } = await context.params;
  const ownerId = await getOwnerId(request);
  if (!ownerId) return unauthorized();

  const body = (await request.json().catch(() => ({}))) as { request?: string; diff?: unknown };
  const store = registryStore();

  try {
    const registry = await store.getById(id);
    if (!registry || registry.ownerId !== ownerId) return Response.json({ error: "Registry not found." }, { status: 404 });

    if (typeof body.request === "string" && body.request.trim()) {
      const diff = await proposeEdit(registry, body.request.slice(0, 500));
      return Response.json({ diff });
    }

    const parsed = EditDiffSchema.safeParse(body.diff);
    if (!parsed.success) return Response.json({ error: "Send a request or a diff." }, { status: 400 });
    const diff = parsed.data;

    const [added, swaps] = await Promise.all([
      withOffers(diff.add, registry.profile),
      mapLimit(diff.swap, 6, async (swap) => ({
        itemId: swap.id,
        searchQuery: swap.searchQuery,
        reason: swap.reason,
        offers: await findOffers(swap.searchQuery, registry.preferredRetailers),
      })),
    ]);
    await store.applyEdits(id, ownerId, diff.remove, added, swaps);
    return Response.json({ ok: true });
  } catch (error) {
    console.error("Edit failed", error);
    return Response.json({ error: error instanceof RegistryError ? error.message : "That edit didn't go through. Try again?" }, { status: 502 });
  }
}

import { registryStore, RegistryError } from "@/lib/registry-store";
import { RETAILERS, type Registry, type RetailerId } from "@/lib/types";

export const runtime = "nodejs";

type RouteContext = { params: Promise<{ slug: string }> };

export type PublicRegistry = Omit<Registry, "ownerId" | "profile">;

function toPublic(registry: Registry): PublicRegistry {
  const { ownerId: _owner, profile: _profile, ...rest } = registry;
  return {
    ...rest,
    items: rest.items
      .filter((i) => i.status !== "skip")
      .map((i) => ({ ...i, purchased: i.purchased ? { buyerName: null, retailer: null } : null })),
  };
}

export async function GET(_request: Request, context: RouteContext) {
  const { slug } = await context.params;
  try {
    const registry = await registryStore().getBySlug(slug);
    if (!registry) return Response.json({ error: "Registry not found." }, { status: 404 });
    return Response.json({ registry: toPublic(registry) }, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return Response.json({ error: error instanceof RegistryError ? error.message : "Could not load registry." }, { status: 503 });
  }
}

export async function POST(request: Request, context: RouteContext) {
  const { slug } = await context.params;
  const body = (await request.json().catch(() => ({}))) as { itemId?: string; buyerName?: string; retailer?: string };
  if (!body.itemId) return Response.json({ error: "Which item did you buy?" }, { status: 400 });
  const retailer = RETAILERS.includes(body.retailer as RetailerId) ? (body.retailer as RetailerId) : null;

  try {
    await registryStore().markPurchased(slug, body.itemId, body.buyerName?.slice(0, 80) ?? null, retailer);
    return Response.json({ ok: true });
  } catch (error) {
    return Response.json({ error: error instanceof RegistryError ? error.message : "Could not mark as purchased." }, { status: 409 });
  }
}

"use client";

import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import type { Category, Offer } from "./types";

const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
const anonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

let browserClient: SupabaseClient | null = null;

export function getBrowserSupabase() {
  if (!url || !anonKey) return null;
  browserClient ??= createClient(url, anonKey);
  return browserClient;
}

export const authEnabled = Boolean(url && anonKey);

export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers);
  headers.set("content-type", "application/json");
  const supabase = getBrowserSupabase();
  if (supabase) {
    const { data } = await supabase.auth.getSession();
    if (data.session) headers.set("authorization", `Bearer ${data.session.access_token}`);
  }
  const response = await fetch(path, { ...init, headers });
  const json = (await response.json().catch(() => ({}))) as T & { error?: string };
  if (!response.ok) throw new Error(json.error ?? "Something went wrong.");
  return json;
}

export function formatPrice(price: number | null) {
  return price === null ? "See price" : `$${price.toFixed(2)}`;
}

export function totalPrice(offers: Offer[], qty: number) {
  const price = offers[0]?.price;
  return price ? price * qty : 0;
