"use client";

import Link from "next/link";
import { use, useMemo, useState } from "react";
import { AuthGate } from "@/components/AuthGate";
import { ItemCard } from "@/components/ItemCard";
import { useRegistry } from "@/components/useRegistry";
import { CATEGORY_ICONS } from "@/lib/client";
import { CATEGORIES, type Category } from "@/lib/types";

export default function ReviewPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  return (
    <AuthGate>
      <Review id={id} />
    </AuthGate>
  );
}

function Review({ id }: { id: string }) {
  const { registry, error, setStatus, setPrimary } = useRegistry(id);
  const [category, setCategory] = useState<Category | null>(null);

  const groups = useMemo(() => {
    if (!registry) return [];
    return CATEGORIES.map((c) => {
      const items = registry.items.filter((i) => i.category === c);
      return { category: c, items, pending: items.filter((i) => i.status === "pending") };
    }).filter((g) => g.items.length > 0);
  }, [registry]);

  if (error && !registry) return <p className="py-20 text-center text-red-600">{error}</p>;
  if (!registry) return <p className="py-20 text-center text-muted">Loading your registry…</p>;

  const total = registry.items.length;
  const reviewed = registry.items.filter((i) => i.status !== "pending").length;
  const progress = total ? reviewed / total : 0;

  const header = (
    <header className="sticky top-0 z-10 space-y-2 bg-cream pt-6 pb-3">
      <div className="flex items-center justify-between text-sm">
        <Link href={`/registry/${id}`} className="text-muted underline">
          Registry overview
        </Link>
        <span className="text-muted">
          {reviewed} of {total} reviewed
        </span>
      </div>
      <div className="h-2 overflow-hidden rounded-full bg-ink/10">
        <div className="h-full rounded-full bg-sage transition-all" style={{ width: `${progress * 100}%` }} />
      </div>
    </header>
  );

  const active = category ? groups.find((g) => g.category === category) : null;
  const current = active?.pending[0];

  if (active) {
    return (
      <main className="space-y-4">
        {header}
        <div className="flex items-center justify-between">
          <h1 className="text-2xl font-bold">
            {CATEGORY_ICONS[active.category]} {active.category}
          </h1>
          <button onClick={() => setCategory(null)} className="text-sm text-muted underline">
            All categories
          </button>
        </div>

        {current ? (
          <>
            <p className="text-sm text-muted">{active.pending.length} left in this category</p>
            <ItemCard key={current.id} item={current} onChooseOffer={(offerId) => void setPrimary(current.id, offerId)}>
              <div className="grid grid-cols-2 gap-3 pt-2">
                <button className="btn-ghost" onClick={() => void setStatus(current.id, "skip")}>
                  Skip
                </button>
                <button className="btn-primary" onClick={() => void setStatus(current.id, "keep")}>
                  Keep
                </button>
              </div>
            </ItemCard>
          </>
        ) : (
          <div className="card space-y-4 text-center">
            <p className="text-4xl">🎉</p>
            <h2 className="text-xl font-semibold">{active.category} is done!</h2>
            <NextCategoryButton groups={groups} onPick={setCategory} id={id} />
          </div>
        )}
      </main>
    );
  }

  return (
    <main className="space-y-4">
      {header}
      <h1 className="text-2xl font-bold">{registry.title}</h1>
      <p className="text-muted">
        Here&apos;s your full draft. Go through it one category at a time, in any order. You can stop whenever you like, and
        your progress is saved.
      </p>
      <div className="grid gap-3">
        {groups.map((g) => {
          const minutes = Math.max(1, Math.round(g.pending.length / 3));
          const done = g.pending.length === 0;
          return (
            <button
              key={g.category}
              onClick={() => setCategory(g.category)}
              className="card flex items-center justify-between text-left hover:bg-white/70"
            >
              <span className="flex items-center gap-3">
                <span className="text-3xl">{CATEGORY_ICONS[g.category]}</span>
                <span>
                  <span className="block font-semibold">{g.category}</span>
                  <span className="text-sm text-muted">
                    {done ? "All reviewed ✓" : `${g.pending.length} items · about ${minutes} min`}
                  </span>
                </span>
              </span>
              <span className="text-muted">→</span>
            </button>
          );
        })}
      </div>
      {progress === 1 && (
        <Link href={`/registry/${id}`} className="btn-primary w-full">
          All done! See and share your registry
        </Link>
      )}
    </main>
  );
}

function NextCategoryButton({
  groups,
  onPick,
  id,
}: {
  groups: Array<{ category: Category; pending: unknown[] }>;
  onPick: (c: Category | null) => void;
  id: string;
}) {
  const next = groups.find((g) => g.pending.length > 0);
  if (!next) {
    return (
      <Link href={`/registry/${id}`} className="btn-primary w-full">
        Everything&apos;s reviewed. See your registry
      </Link>
    );
  }
  return (
    <button className="btn-primary w-full" onClick={() => onPick(next.category)}>
      Next: {CATEGORY_ICONS[next.category]} {next.category}
    </button>
  );
}

"use client";

import Link from "next/link";
import { use, useState } from "react";
import { AuthGate } from "@/components/AuthGate";
import { ItemCard } from "@/components/ItemCard";
import { useRegistry } from "@/components/useRegistry";
import { api, CATEGORY_ICONS, totalPrice } from "@/lib/client";
import { CATEGORIES, type EditDiff, type Registry } from "@/lib/types";

export default function RegistryPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  return (
    <AuthGate>
      <Overview id={id} />
    </AuthGate>
  );
}

function Overview({ id }: { id: string }) {
  const { registry, error, reload, setStatus, setPrimary } = useRegistry(id);

  if (error && !registry) return <p className="py-20 text-center text-red-600">{error}</p>;
  if (!registry) return <p className="py-20 text-center text-muted">Loading your registry…</p>;

  const kept = registry.items.filter((i) => i.status !== "skip");
  const pending = registry.items.filter((i) => i.status === "pending").length;
  const purchased = kept.filter((i) => i.purchased).length;
  const total = kept.reduce((sum, i) => sum + totalPrice(i.offers, i.qty), 0);

  return (
    <main className="space-y-6 pt-6">
      <header className="space-y-2">
        <Link href="/" className="text-sm text-muted underline">
          Home
        </Link>
        <h1 className="text-2xl font-bold">{registry.title}</h1>
        <p className="text-muted">
          {kept.length} items · about ${Math.round(total).toLocaleString()} · {purchased} gifted
        </p>
      </header>

      {pending > 0 && (
        <Link href={`/registry/${id}/review`} className="card block bg-blush/60 font-medium">
          {pending} items still to review. Continue where you left off →
        </Link>
      )}

      <ShareBox slug={registry.slug} />
      <EditBox registry={registry} onApplied={reload} />

      {CATEGORIES.map((category) => {
        const items = kept.filter((i) => i.category === category);
        if (!items.length) return null;
        return (
          <section key={category} className="space-y-3">
            <h2 className="text-lg font-semibold">
              {CATEGORY_ICONS[category]} {category}
            </h2>
            {items.map((item) => (
              <ItemCard key={item.id} item={item} onChooseOffer={(offerId) => void setPrimary(item.id, offerId)}>
                <div className="flex items-center justify-between text-sm">
                  {item.purchased ? (
                    <span className="font-medium text-sage-dark">🎁 Gifted</span>
                  ) : (
                    <button className="text-muted underline" onClick={() => void setStatus(item.id, "skip")}>
                      Remove
                    </button>
                  )}
                </div>
              </ItemCard>
            ))}
          </section>
        );
      })}
    </main>
  );
}

function ShareBox({ slug }: { slug: string }) {
  const [copied, setCopied] = useState(false);
  const url = typeof window === "undefined" ? `/r/${slug}` : `${window.location.origin}/r/${slug}`;

  async function share() {
    if (navigator.share) {
      await navigator.share({ title: "Our baby registry", url }).catch(() => undefined);
      return;
    }
    await navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <div className="card flex items-center justify-between gap-3">
      <div className="min-w-0">
        <p className="font-semibold">Share with family &amp; friends</p>
        <p className="truncate text-sm text-muted">{url}</p>
      </div>
      <button className="btn-primary shrink-0" onClick={() => void share()}>
        {copied ? "Copied!" : "Share"}
      </button>
    </div>
  );
}

const SUGGESTIONS = ["Make it cheaper", "We already have a crib", "More eco-friendly", "Add a baby swing"];

function EditBox({ registry, onApplied }: { registry: Registry; onApplied: () => Promise<void> }) {
  const [text, setText] = useState("");
  const [diff, setDiff] = useState<EditDiff | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const names = new Map(registry.items.map((i) => [i.id, i.name]));

  async function propose(request: string) {
    if (!request.trim()) return;
    setBusy(true);
    setError("");
    try {
      const { diff } = await api<{ diff: EditDiff }>(`/api/registries/${registry.id}/edit`, {
        method: "POST",
        body: JSON.stringify({ request }),
      });
      setDiff(diff);
    } catch (e) {
      setError(e instanceof Error ? e.message : "That didn't work.");
    } finally {
      setBusy(false);
    }
  }

  async function apply() {
    if (!diff) return;
    setBusy(true);
    try {
      await api(`/api/registries/${registry.id}/edit`, { method: "POST", body: JSON.stringify({ diff }) });
      setDiff(null);
      setText("");
      await onApplied();
    } catch (e) {
      setError(e instanceof Error ? e.message : "That didn't work.");
    } finally {
      setBusy(false);
    }
  }

  const hasChanges = diff && (diff.add.length || diff.remove.length || diff.swap.length);

  return (
    <div className="card space-y-3">
      <p className="font-semibold">Change anything by just saying it</p>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          void propose(text);
        }}
        className="flex gap-2"
      >
        <input
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="e.g. we're getting a hand-me-down stroller"
          className="flex-1 rounded-full border border-ink/15 bg-cream px-4 py-2.5 outline-none focus:border-sage"
        />
        <button className="btn-primary" disabled={busy || !text.trim()}>
          {busy ? "…" : "Go"}
        </button>
      </form>
      {!diff && (
        <div className="flex flex-wrap gap-2">
          {SUGGESTIONS.map((s) => (
            <button
              key={s}
              className="chip text-xs"
              disabled={busy}
              onClick={() => {
                setText(s);
                void propose(s);
              }}
            >
              {s}
            </button>
          ))}
        </div>
      )}
      {error && <p className="text-sm text-red-600">{error}</p>}
      {diff && (
        <div className="space-y-3 rounded-2xl bg-cream p-4 text-sm">
          <p className="font-medium">{diff.summary}</p>
          <ul className="space-y-1 text-muted">
            {diff.remove.map((id) => (
              <li key={id}>− Remove {names.get(id)}</li>
            ))}
            {diff.add.map((item) => (
              <li key={item.name}>+ Add {item.name}</li>
            ))}
            {diff.swap.map((s) => (
              <li key={s.id}>
                ↻ {names.get(s.id)} → &ldquo;{s.searchQuery}&rdquo;
              </li>
            ))}
          </ul>
          <div className="flex gap-2">
            <button className="btn-ghost flex-1" onClick={() => setDiff(null)} disabled={busy}>
              Never mind
            </button>
            {hasChanges ? (
              <button className="btn-primary flex-1" onClick={() => void apply()} disabled={busy}>
                {busy ? "Updating…" : "Looks good"}
              </button>
            ) : null}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { use, useCallback, useEffect, useState } from "react";
import { CATEGORY_ICONS, formatPrice, getBrowserSupabase, PRIORITY_LABELS } from "@/lib/client";
import { CATEGORIES, RETAILER_LABELS, type Registry, type RegistryItem, type RetailerId } from "@/lib/types";

type PublicRegistry = Omit<Registry, "ownerId" | "profile">;

const POLL_MS = 15000;

export default function SharePage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = use(params);
  const [registry, setRegistry] = useState<PublicRegistry | null>(null);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    const response = await fetch(`/api/r/${slug}`, { cache: "no-store" });
    const data = (await response.json()) as { registry?: PublicRegistry; error?: string };
    if (data.registry) setRegistry(data.registry);
    else setError(data.error ?? "Registry not found.");
  }, [slug]);

  useEffect(() => {
    void load();
    const supabase = getBrowserSupabase();
    if (!supabase) {
      const timer = setInterval(() => void load(), POLL_MS);
      return () => clearInterval(timer);
    }
    const channel = supabase
      .channel(`registry:${slug}`)
      .on("broadcast", { event: "registry_changed" }, () => void load())
      .subscribe();
    return () => {
      void supabase.removeChannel(channel);
    };
  }, [load, slug]);

  if (error) return <p className="py-20 text-center text-muted">{error}</p>;
  if (!registry) return <p className="py-20 text-center text-muted">Loading…</p>;

  const gifted = registry.items.filter((i) => i.purchased).length;

  return (
    <main className="space-y-6 pt-10">
      <header className="space-y-2 text-center">
        <p className="text-4xl">🍼</p>
        <h1 className="text-2xl font-bold">{registry.title}</h1>
        {registry.dueDate && (
          <p className="text-muted">
            Due {new Date(registry.dueDate + "T00:00:00").toLocaleDateString(undefined, { month: "long", year: "numeric" })}
          </p>
        )}
        <p className="text-sm text-muted">
          {gifted} of {registry.items.length} gifted. Thank you for helping us get ready!
        </p>
      </header>

      {CATEGORIES.map((category) => {
        const items = registry.items.filter((i) => i.category === category);
        if (!items.length) return null;
        return (
          <section key={category} className="space-y-3">
            <h2 className="text-lg font-semibold">
              {CATEGORY_ICONS[category]} {category}
            </h2>
            {items.map((item) => (
              <GiftCard key={item.id} item={item} slug={slug} onBought={load} />
            ))}
          </section>
        );
      })}
    </main>
  );
}

function GiftCard({ item, slug, onBought }: { item: RegistryItem; slug: string; onBought: () => Promise<void> }) {
  const [confirming, setConfirming] = useState<RetailerId | null>(null);
  const [name, setName] = useState("");
  const [error, setError] = useState("");
  const primary = item.offers[0];

  async function markBought() {
    setError("");
    const response = await fetch(`/api/r/${slug}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ itemId: item.id, buyerName: name, retailer: confirming }),
    });
    const data = (await response.json()) as { error?: string };
    if (!response.ok) setError(data.error ?? "That didn't work.");
    setConfirming(null);
    await onBought();
  }

  return (
    <article className={`card space-y-3 ${item.purchased ? "opacity-60" : ""}`}>
      <div className="flex items-start gap-4">
        <div className="flex h-16 w-16 shrink-0 items-center justify-center overflow-hidden rounded-2xl bg-cream text-3xl">
          {primary?.imageUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img src={primary.imageUrl} alt="" className="h-full w-full object-contain" />
          ) : (
            CATEGORY_ICONS[item.category]
          )}
        </div>
        <div className="min-w-0 flex-1">
          <p className="text-xs text-muted">{PRIORITY_LABELS[item.priority]}</p>
          <h3 className="font-semibold">
            {item.name}
            {item.qty > 1 && <span className="font-normal text-muted"> × {item.qty}</span>}
          </h3>
          <p className="truncate text-sm text-muted">{primary?.title}</p>
        </div>
      </div>

      {item.purchased ? (
        <p className="text-center font-medium text-sage-dark">🎁 Already gifted</p>
      ) : confirming ? (
        <div className="space-y-2 rounded-2xl bg-cream p-3">
          <p className="text-sm">Did you buy it? Let them know so nobody doubles up.</p>
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Your name (optional)"
            className="w-full rounded-full border border-ink/15 bg-white px-4 py-2 outline-none focus:border-sage"
          />
          <div className="flex gap-2">
            <button className="btn-ghost flex-1" onClick={() => setConfirming(null)}>
              Not yet
            </button>
            <button className="btn-primary flex-1" onClick={() => void markBought()}>
              Yes, I bought it
            </button>
          </div>
        </div>
      ) : (
        <div className="flex flex-wrap gap-2">
          {item.offers.map((offer) => (
            <a
              key={offer.id}
              href={offer.url}
              target="_blank"
              rel="noopener noreferrer sponsored"
              onClick={() => setConfirming(offer.retailer)}
              className="chip"
            >
              {RETAILER_LABELS[offer.retailer]} · {formatPrice(offer.price)}
            </a>
          ))}
          <button className="text-sm text-muted underline" onClick={() => setConfirming(primary?.retailer ?? "amazon")}>
            Bought it elsewhere
          </button>
        </div>
      )}
      {error && <p className="text-sm text-red-600">{error}</p>}
    </article>
  );
}

